 [HideInInspector]public int playtestAudioRepairVersion;public int kickSoundIndex=7;float nextPostSound;public SportsEventTruck truck;public FieldGoalProjectile football,truckFlight;public FieldGoalBoot boot;public Collider ground;public Transform posts,tee,bootMechanism;public SportsEventCamera cameraRig;public SportsMotionReplay replay;public SportsChaosWeather atmosphere;public SportsWeatherPresets weatherPresets;public FieldGoalFlightModel flightModel=new FieldGoalFlightModel();public Transform endZone;public AudioSource flightWind;public TMP_Text practiceDistanceText;public GameObject practiceRetry;public ParticleSystem kickBurst;public FieldGoalRules rules=new FieldGoalRules();public int seed=18361,practiceDistance=2;public FieldGoalPhase Phase{get;private set;}public float Clock{get;private set;}public float PhaseAge{get;private set;}public float FlightAge{get;private set;}public float Timing{get;private set;}public string Outcome{get;private set;}="";public Vector3 CurrentWind{get;private set;}public bool IsTruck=>false;public bool Practice=>option==1;public float GoalZ=>Distances[Practice?Mathf.Clamp(practiceDistance,0,4):rules.Round>5?(rules.Round-6)%5:Mathf.Clamp(rules.Round-1,0,4)];public float GoalHalfWidth=>2.82f;public float Crossbar=>3.05f;public FieldGoalProjectile Projectile=>IsTruck?truckFlight:football;public readonly SportsLimitedAftertouch correction=new SportsLimitedAftertouch();
