 public override string Help=>"BUMPER KICK\nLine up behind the upright football and drive into it. The truck is the kicking foot. Actual bumper speed, angle, contact point and spin determine the kick. No launch button and no airborne ball control.\n\nFIVE ATTEMPTS each at progressively greater distances. One point for a forward center crossing BETWEEN uprights and ABOVE the crossbar before first airborne ground contact. Side/back/below/wide entries are not goals. A real post/crossbar ricochet followed by a legal forward crossing counts. Swept crossing prevents fast tunneling; physics contact chronology takes precedence over callback order. Once GOOD, later collisions cannot revoke it. Tied leaders receive equal-opportunity extra rounds cycling the same five distances; first shooter rotates. All participants use the same goal geometry, wind and contact rules.\n\nSOLO PRACTICE selects a fixed distance and keeps retrying. Practice keeps the established bumper-kick personal best. Sequential hot seat may reuse a keyboard or controller; inactive players cannot affect the attempt. AI drives into the same real contacts without homing or direct score awards. Actual-motion replay has angle, slow/normal/fast, rewind and skip. Pause/reconnect preserves the attempt; release inputs before fresh confirmation.\n\nWEATHER: choose Random or any installed forecast before starting. One forecast lasts the match; only Random rerolls on rematch. Actual wind and gusts affect drag and spin throughout flight, and wet/snow conditions reduce truck grip. The MPH card and windsock show the same wind; its arrow is relative to the camera view. Offline only.";
 protected override void Awake(){base.Awake();baseGrip=truck!=null?truck.grip:1.35f;matchSerial=SportsPrefs.GetInt("TruckFieldGoal.ForecastSequence",0);practiceDistance=Mathf.Clamp(SportsPrefs.GetInt("TruckFieldGoal.PracticeDistance",2),0,4);}
 protected override void BeginGame(){rules.Reset(setup.count,Practice);MatchSeed=unchecked(seed+matchSerial*104729);weatherAge=0;Forecast=weatherPresets.Resolve(MatchSeed);atmosphere.ConfigurePreset(Forecast,MatchSeed);matchSerial=unchecked(matchSerial+1);SportsPrefs.SetInt("TruckFieldGoal.ForecastSequence",matchSerial);SportsPrefs.Save();PrepareAttempt();}
 void PrepareAttempt(){carnivalPresentation?.ResetAttemptPresentation();nextPostSound=0;GetComponent<FieldGoalHolderPresentation>()?.ResetPresentation();GetComponent<FieldGoalCrowd>()?.ResetAttempt();replay.End();SportsLaunchAppearanceBoundary.PrepareTurn(truck,setup.players[rules.Current],rules.Current,replay);truck.visuals.gameObject.SetActive(true);football.gameObject.SetActive(true);boot.gameObject.SetActive(IsTruck);bootMechanism.gameObject.SetActive(IsTruck);tee.gameObject.SetActive(!IsTruck);Clock=PhaseAge=FlightAge=Timing=0;timingCommitted=false;planned=false;Outcome="";Phase=FieldGoalPhase.Countdown;posts.position=new Vector3(0,0,GoalZ);stadiumBoard?.AlignField();if(endZone!=null)endZone.position=new Vector3(0,.018f,GoalZ-4.572f);truck.grip=baseGrip*atmosphere.Grip;truck.slot=rules.Current;truck.Prepare(new Vector3(0,.7f,IsTruck?-13:-27),Quaternion.identity);football.body.isKinematic=true;football.body.detectCollisions=!IsTruck;football.body.position=new Vector3(0,1.23f,0);football.body.rotation=Quaternion.identity;football.transform.SetPositionAndRotation(football.body.position,football.body.rotation);Physics.IgnoreCollision(football.shape,truck.shape,false);football.ResetShot();football.gameObject.SetActive(!IsTruck);truckFlight.ResetShot();boot.ResetBoot();correction.Reset(1.6f,Vector2.zero);kickBurst.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);atmosphere.Tick(weatherAge);CurrentWind=atmosphere.Flow;replay.Colorize(new[]{setup.players[rules.Current].color,Color.white,Color.white});SportsLaunchAppearanceBoundary.RefreshRecord(replay,0);replay.ResetRecord();var random=new System.Random(seed+rules.Round*1009+rules.Current*7919);float skill=(int)setup.players[rules.Current].difficulty;aimX=(float)(random.NextDouble()*2-1)*Mathf.Lerp(.75f,.12f,skill*.5f);entryAngle=(float)(random.NextDouble()*2-1)*Mathf.Lerp(14,6,skill*.5f)-Mathf.Atan2(CurrentWind.x*.4f,GoalZ)*Mathf.Rad2Deg*Mathf.Lerp(.2f,.9f,skill*.5f);entrySpeed=IsTruck?7:Mathf.Sqrt(1.8f*GoalZ*GoalZ/Mathf.Max(1,.424f*GoalZ-5.35f));entrySpeed+=(float)(random.NextDouble()*2-1)*Mathf.Lerp(3.4f,.65f,skill*.5f);tapTime=.7f+(float)(random.NextDouble()*2-1)*Mathf.Lerp(.48f,.23f,skill*.5f);aiThink=0;ai=Vector2.zero;botAction=false;cameraRig.rig.PreviousStateIsValid=false;Physics.SyncTransforms();Gate();}
 protected override void Simulate(float dt){weatherAge+=dt;atmosphere.Tick(weatherAge);CurrentWind=atmosphere.Flow;if(Projectile.Launched&&!rules.AttemptLocked)Projectile.Observe();Clock+=dt;PhaseAge+=dt;if(IsTruck&&boot.Stroking&&Phase!=FieldGoalPhase.Replay)boot.Tick(dt);if(Phase==FieldGoalPhase.Replay){if(replay.Step(dt)||PhaseAge>18){replay.End();truck.visuals.gameObject.SetActive(true);football.gameObject.SetActive(!IsTruck);boot.gameObject.SetActive(IsTruck);Phase=FieldGoalPhase.AttemptResult;PhaseAge=0;}return;}if(Phase==FieldGoalPhase.AttemptResult){if(PhaseAge>=1.2f){rules.Advance();if(rules.Complete){if(setup.count==1){SportsPrefs.SetInt(BestKey,Mathf.Max(SportsPrefs.GetInt(BestKey,0),rules.goals[0]));SportsPrefs.Save();}EndMatch();}else PrepareAttempt();}return;}if(Phase==FieldGoalPhase.Countdown){Brake(Vector2.zero);if(!planned&&PhaseAge>=2.6f&&setup.players[rules.Current].source==BowlingSource.AI){PlanBot();planned=true;}if(PhaseAge>=3){Phase=FieldGoalPhase.Approach;PhaseAge=0;}return;}
  Vector2 drive=commands[rules.Current];bool action=actions[rules.Current];if(setup.players[rules.Current].source==BowlingSource.AI){Bot(dt);drive=ai;action=botAction;}if(Phase==FieldGoalPhase.Approach){truck.TickDrive(drive);if(IsTruck&&truck.body.position.z>=-2.6f&&truck.body.position.z<=2.2f&&Mathf.Abs(truck.body.position.x)<3){Phase=FieldGoalPhase.Windup;PhaseAge=0;}if(PhaseAge>35||truck.body.position.y< -4||Mathf.Abs(truck.body.position.x)>25||truck.body.position.z>(IsTruck?5:15))Resolve(false,IsTruck?"MISSED THE BOOT":"MISSED THE BALL",truck.body.position);}
  else if(Phase==FieldGoalPhase.Windup){Brake(drive);if(action&&!timingCommitted){timingCommitted=true;Timing=Mathf.Clamp01(1-Mathf.Abs(PhaseAge-.7f)/.7f);Phase=FieldGoalPhase.BootSwing;PhaseAge=0;boot.Begin();feedback.Play(0,0,true);}else if(PhaseAge>1.5f)Resolve(false,"NO TIMED KICK",truck.body.position);}
  else if(Phase==FieldGoalPhase.BootSwing){Brake(Vector2.zero);if(PhaseAge>1.2f&&!truckFlight.Launched)Resolve(false,"OUTSIDE BOOT REACH",truck.body.position);}
  else if(Phase==FieldGoalPhase.Flight){FlightAge+=dt;if(IsTruck)correction.Tick(truck.body,drive,dt);Projectile.body.AddForce(flightModel.AirAcceleration(Projectile.body.linearVelocity,Projectile.body.angularVelocity,CurrentWind),ForceMode.Acceleration);var p=Projectile.Reference;if(FlightAge>12||p.y< -5||Mathf.Abs(p.x)>65||p.z>GoalZ+35||p.z< -25||FlightAge>.5f&&!Projectile.ClearedGround&&Projectile.shape.bounds.min.y<.13f)Resolve(false,string.IsNullOrEmpty(Projectile.LastMissLabel)?"SHORT / OUT OF PLAY":Projectile.LastMissLabel,p);}
  else if(Phase==FieldGoalPhase.Aftermath&&PhaseAge>2.2f&&!(GetComponent<FieldGoalStadiumAntics>()?.VignetteActive??false))BeginReplay();replay.Record(Clock,IsTruck?5:3);
 }
 void Brake(Vector2 drive){truck.TickDrive(new Vector2(drive.x,0));foreach(var wheel in truck.wheels){wheel.MotorTorque=0;wheel.BrakeTorque=truck.brakeTorque;}}
 void PlanBot(){
  // Estimate one approach using the same kick/aerodynamic model. Execution still
  // requires NWH steering, actual bumper contact and the same changing wind.
  float skill=(int)setup.players[rules.Current].difficulty,nominal=Mathf.Sqrt(1.8f*GoalZ*GoalZ/Mathf.Max(1,.424f*GoalZ-5.35f));
  float best=float.PositiveInfinity,bestHeading=0,bestSpeed=nominal;var wind=CurrentWind*Mathf.Lerp(.45f,1,skill*.5f);
  for(float speed=10;speed<=20;speed+=1)for(float heading=-28;heading<=28;heading+=2){
   var incoming=Quaternion.Euler(0,heading,0)*Vector3.forward*speed;flightModel.Kick(incoming,Vector3.zero,.46f,out var v,out var spin);var p=new Vector3(0,1.23f,0);bool crossed=false;
   for(int step=0;step<220;step++){var previous=p;v+=(Physics.gravity+flightModel.AirAcceleration(v,spin,wind))*.04f;v*=1-.025f*.04f;spin*=1-.025f*.04f;p+=v*.04f;if(p.z>=GoalZ){p=Vector3.Lerp(previous,p,Mathf.InverseLerp(previous.z,p.z,GoalZ));crossed=true;break;}if(p.y<.3f||v.z<=0)break;}
   float cost=crossed?Mathf.Abs(p.x)+Mathf.Max(0,Crossbar+1.5f-p.y)*3:30+Mathf.Abs(GoalZ-p.z);
   cost+=Mathf.Abs(speed-nominal)*.06f+Mathf.Abs(heading)*.005f;
   if(cost<best){best=cost;bestHeading=heading;bestSpeed=speed;}
  }
  entryAngle+=bestHeading;entrySpeed+=bestSpeed-nominal;
 }
 void Bot(float dt){botAction=false;aiThink-=dt;if(aiThink>0)return;float skill=(int)setup.players[rules.Current].difficulty;aiThink=Mathf.Lerp(.22f,.065f,skill*.5f);var p=truck.body.position;var forward=Vector3.ProjectOnPlane(truck.body.rotation*Vector3.forward,Vector3.up);if(Phase==FieldGoalPhase.Approach){float targetZ=p.z<-17?-16:p.z+6;float x=aimX+Mathf.Tan(entryAngle*Mathf.Deg2Rad)*targetZ;var delta=new Vector3(x-p.x,0,Mathf.Max(2,targetZ-p.z));float angle=Vector3.SignedAngle(forward,delta,Vector3.up);ai=new Vector2(Mathf.Clamp(angle/24,-1,1),Mathf.Clamp((entrySpeed-truck.body.linearVelocity.z)*.5f,-.8f,1));}else if(Phase==FieldGoalPhase.Windup){ai=Vector2.zero;botAction=PhaseAge>=tapTime;}else if(Phase==FieldGoalPhase.Flight&&IsTruck){var b=truck.body;float time=Mathf.Max(0,(b.linearVelocity.y+Mathf.Sqrt(b.linearVelocity.y*b.linearVelocity.y+2*9.81f*Mathf.Max(0,b.position.y)))/9.81f);float prediction=b.position.x+b.linearVelocity.x*time;ai=new Vector2(Mathf.Clamp((-prediction+aimX)*Mathf.Lerp(.06f,.2f,skill*.5f),-1,1),FlightAge<.35f?0:Mathf.Clamp((GoalZ-b.position.z-b.linearVelocity.z*time)*.04f,-1,1));}else ai=Vector2.zero;}
 public void FootContact(Collision collision){if(IsTruck||Phase!=FieldGoalPhase.Approach||football.Launched)return;var incoming=Vector3.ProjectOnPlane(-collision.relativeVelocity,Vector3.up);if(Vector3.Dot(incoming,truck.body.rotation*Vector3.forward)<0)incoming=-incoming;float speed=incoming.magnitude;if(speed<1.5f)return;var point=collision.GetContact(0).point;flightModel.Kick(incoming,point-football.Reference,.46f,out var desired,out var spin);football.body.isKinematic=false;football.body.AddForce(desired-football.body.linearVelocity,ForceMode.VelocityChange);football.body.angularVelocity=spin;truck.Power(false);Physics.IgnoreCollision(football.shape,truck.shape,true);football.Arm();Launched(point);}
 public void BootContact(Vector3 point){if(!IsTruck||Phase!=FieldGoalPhase.BootSwing||truckFlight.Launched||!timingCommitted)return;var velocity=boot.body.GetPointVelocity(point);var along=Vector3.ProjectOnPlane(velocity,Vector3.up);if(along.magnitude<1)return;var facing=Vector3.ProjectOnPlane(truck.body.rotation*Vector3.forward,Vector3.up).normalized;var direction=(along.normalized*.7f+facing*.3f).normalized;float quality=.45f+.55f*Timing;var desired=direction*(Mathf.Clamp(18+along.magnitude*.45f,18,32)*quality)+Vector3.up*(Mathf.Clamp(14+Mathf.Abs(velocity.y)*.15f,14,17)*quality);truck.Power(false);truck.body.AddForce(desired-truck.body.linearVelocity,ForceMode.VelocityChange);var spin=Vector3.ClampMagnitude(Vector3.Cross(point-truck.body.worldCenterOfMass,desired)*.055f,3);truck.body.AddTorque(spin-truck.body.angularVelocity,ForceMode.VelocityChange);correction.Reset(1.6f,commands[rules.Current]);truckFlight.Arm();Launched(point);}
 void Launched(Vector3 point){carnivalPresentation?.RecordKick(Clock);Phase=FieldGoalPhase.Flight;PhaseAge=FlightAge=0;kickBurst.transform.position=point;kickBurst.Play();feedback.Play(feedback.clips!=null&&kickSoundIndex>=0&&kickSoundIndex<feedback.clips.Length&&feedback.clips[kickSoundIndex]!=null?kickSoundIndex:1,14,true);Pulse(rules.Current,.4f,.18f);Debug.Log("FIELD_GOAL_ACTUAL_KICK variant="+(IsTruck?"Truck":"Foot")+" round="+rules.Round+" shooter="+rules.Current+" point="+point+" queuedPhysicsResponse=true timing="+Timing);}
 public void Resolve(bool good,string reason,Vector3 point){if(!Live||!rules.Lock(good))return;if(good)ConfirmScore("kick:"+rules.Current+":"+rules.attempts[rules.Current],rules.Current,1,rules.goals[rules.Current],"FIELD GOAL!",SportsScoreTier.Major);if(good)GetComponent<FieldGoalHolderPresentation>()?.Celebrate();var crowd=GetComponent<FieldGoalCrowd>();crowd?.React(good,reason,point);Outcome=reason;Phase=FieldGoalPhase.Aftermath;PhaseAge=0;truck.Power(false);if(crowd==null||crowd.response==null||(good?crowd.cheer:crowd.boo)==null)feedback.Play(good?5:3,0,true);Pulse(rules.Current,good?.6f:.2f,.2f);{string key="TruckFieldGoal.Statistics."+(IsTruck?"Football":"Foot");SportsPrefs.SetInt(key+".Attempts",SportsPrefs.GetInt(key+".Attempts",0)+1);if(good)SportsPrefs.SetInt(key+".Goals",SportsPrefs.GetInt(key+".Goals",0)+1);SportsPrefs.Save();}Debug.Log("FIELD_GOAL_RESULT variant="+(IsTruck?"Truck":"Foot")+" round="+rules.Round+" shooter="+rules.Current+" good="+good+" reason="+reason+" point="+point);}
 public void PostHit(float speed){if(!Live||rules.AttemptLocked||Time.unscaledTime<nextPostSound)return;nextPostSound=Time.unscaledTime+.12f;feedback.Play(1,speed);Pulse(rules.Current,.18f,.08f);}
 void BeginReplay(){carnivalPresentation?.CaptureReplayTruckAnchor();replay.Record(Clock+.051f,IsTruck?5:3);truck.Power(false);truck.body.isKinematic=true;truck.body.detectCollisions=false;football.body.isKinematic=true;football.body.detectCollisions=false;truck.visuals.gameObject.SetActive(false);football.gameObject.SetActive(false);boot.gameObject.SetActive(false);Phase=FieldGoalPhase.Replay;PhaseAge=0;replay.Begin(0);replay.Speed=Mathf.Max(1,replay.Duration/12f);Gate();}
 public override void ExtraAction(string key){if(key=="distance"&&!Running){practiceDistance=(practiceDistance+1)%5;SportsPrefs.SetInt("TruckFieldGoal.PracticeDistance",practiceDistance);Save();return;}if(key=="retry"&&Practice&&Running&&!Paused){if(rules.AttemptLocked)rules.Advance();PrepareAttempt();return;}if(Phase!=FieldGoalPhase.Replay)return;if(key=="replayangle")replay.Angle=(replay.Angle+1)%3;else if(key=="replayspeed")replay.Speed=replay.Speed==1?.5f:replay.Speed==.5f?2:1;else if(key=="replayrewind")replay.Seek(Mathf.Max(0,replay.Cursor-3));else if(key=="replayskip")PhaseAge=19;ConsumeActions();}
 protected override void Present(float dt){if(cameraRig==null||truck==null)return;if(practiceRetry!=null&&practiceRetry.activeSelf!=Practice)practiceRetry.SetActive(Practice);bool recorded=Phase==FieldGoalPhase.Replay;var focus=recorded?replay.Position(IsTruck||!football.Launched?0:1):Phase==FieldGoalPhase.Flight||Phase==FieldGoalPhase.Aftermath?(IsTruck||football.Launched?Projectile.Reference:truck.body.worldCenterOfMass):truck.body.worldCenterOfMass+Vector3.forward*6;Vector3 offset=recorded?(replay.Angle==0?new Vector3(10,6,-12):replay.Angle==1?new Vector3(-12,5,7):new Vector3(0,20,-2)):Phase==FieldGoalPhase.Flight?new Vector3(0,4,-10):new Vector3(0,3.5f,-9);var stadiumAntics=GetComponent<FieldGoalStadiumAntics>();if(stadiumAntics!=null&&stadiumAntics.VignetteActive){focus=(stadiumAntics.referee.position+stadiumAntics.InvaderPosition)*.5f;offset=new Vector3(15,10,-20);}float viewFov=60;if(stadiumBoard!=null&&!recorded&&!(stadiumAntics!=null&&stadiumAntics.VignetteActive)){float distanceView=Mathf.InverseLerp(30,62,GoalZ);bool flight=Phase==FieldGoalPhase.Flight||Phase==FieldGoalPhase.Aftermath;if(!flight)viewFov=Mathf.Lerp(60,45,distanceView);var position=flight?focus+offset:truck.body.worldCenterOfMass+new Vector3(0,5,-Mathf.Lerp(13,19,distanceView));var viewAim=Phase==FieldGoalPhase.Flight||Phase==FieldGoalPhase.Aftermath?focus:new Vector3(truck.body.position.x*.25f,10,Mathf.Lerp(truck.body.position.z,GoalZ,.68f));focus=viewAim;offset=position-viewAim;}if(!recorded&&Phase==FieldGoalPhase.Aftermath&&PhaseAge>.12f&&!(stadiumAntics!=null&&stadiumAntics.VignetteActive)){var holder=GetComponent<FieldGoalHolderPresentation>();if(holder!=null&&holder.CelebratedAttempt){focus=holder.holder.position+Vector3.up*.95f;offset=new Vector3(4.5f,3.2f,-7.5f);viewFov=55;}}bool boardView=false;if(recorded&&carnivalPresentation!=null&&carnivalPresentation.TryDescribeBoardShot(out var boardFocus,out var boardOffset,out var boardFov)){boardView=true;focus=boardFocus;offset=boardOffset;viewFov=boardFov;}cameraRig.Pose(focus,offset,Mathf.Lerp(cameraRig.view.fieldOfView,viewFov,1-Mathf.Exp(-5*Time.unscaledDeltaTime)),boardView&&carnivalPresentation.BoardShotFresh);if(flightWind!=null){flightWind.volume=Live&&Phase==FieldGoalPhase.Flight&&Application.isFocused?settings.sfx*.04f:0;if(flightWind.volume>0&&!flightWind.isPlaying)flightWind.Play();else if(flightWind.volume<=0)flightWind.Stop();}}
 protected override void SetPaused(bool paused){if(atmosphere!=null)atmosphere.Pause(paused);}protected override void StopSounds(){if(truck!=null)truck.StopSound();if(flightWind!=null)flightWind.Stop();}protected override void StopGame(){carnivalPresentation?.Close();GetComponent<FieldGoalHolderPresentation>()?.ResetPresentation();GetComponent<FieldGoalCrowd>()?.ResetAttempt();if(replay!=null)replay.End();if(truck!=null){truck.Power(false);truck.body.isKinematic=true;truck.body.detectCollisions=false;}if(football!=null){football.body.isKinematic=true;football.body.detectCollisions=false;}}
}
